def classify(status):
    kind = status // 100
    if kind == 2:
        return "success"
    if kind == 3:
        return "redirect"
    if kind == 4:
        return "client error"
    if kind == 5:
        return "server error"
    raise ValueError(f"Unknown status {status}")

